#include "MaxHeap.h"
#include "Database.h"
#include <arpa/inet.h>
#include <sys/socket.h>
#include <unistd.h>
#include <ctime>
#include <iomanip>
#include <sstream>
#include <iostream>
#include <mutex>
#include <chrono>
#include <algorithm>
#include <cerrno>
#include <cstring>
#include <cstdlib>
static std::mutex mu; static MaxHeap heap; static std::vector<Patient> treated; static Database db("hospital.db");
static std::string esc(std::string s){std::string o;for(char c:s){if(c=='"'||c=='\\')o+='\\';if(c=='\n')o+="\\n";else if(c!='\r')o+=c;}return o;}
static std::string js(const Patient&p){std::ostringstream o;o<<"{\"patientID\":\""<<esc(p.patientID)<<"\",\"name\":\""<<esc(p.name)<<"\",\"age\":"<<p.age<<",\"gender\":\""<<esc(p.gender)<<"\",\"condition\":\""<<esc(p.condition)<<"\",\"severity\":"<<p.severity<<",\"originalSeverity\":"<<(p.originalSeverity?p.originalSeverity:p.severity)<<",\"arrivalTime\":\""<<esc(p.arrivalTime)<<"\",\"arrivalEpoch\":"<<p.arrivalEpoch<<",\"emergencyCategory\":\""<<esc(p.emergencyCategory)<<"\",\"treatmentTime\":\""<<esc(p.treatmentTime)<<"\",\"waitSeconds\":"<<p.waitSeconds<<"}";return o.str();}
static std::string field(const std::string&b,const std::string&k){auto i=b.find("\""+k+"\"");if(i==std::string::npos)return "";i=b.find(':',i)+1;while(i<b.size()&&b[i]==' ')++i;if(b[i]=='\"'){auto j=b.find('"',i+1);return b.substr(i+1,j-i-1);}auto j=b.find_first_of(",}",i);return b.substr(i,j-i);}
static std::string arr(const std::vector<Patient>&v){std::string o="[";for(size_t i=0;i<v.size();++i){if(i)o+=',';o+=js(v[i]);}return o+"]";}
static std::string now(){std::time_t t=time(nullptr);std::tm tm=*std::localtime(&t);std::ostringstream o;o<<std::put_time(&tm,"%Y-%m-%d %H:%M:%S");return o.str();}
static std::string route(std::string method,std::string path,std::string body){std::lock_guard<std::mutex> lock(mu);auto q=heap.displayPatients();if(method=="GET"&&path=="/api/patients/queue")return arr(q);if(method=="GET"&&path=="/api/patients/history")return arr(treated);
 if(method=="GET"&&path=="/api/analytics"){std::ostringstream a;a<<"{\"severityCounts\":[";for(int s=5;s>=1;--s){if(s<5)a<<',';int w=0,t=0;for(auto&p:q)w+=p.severity==s;for(auto&p:treated)t+=p.severity==s;a<<"{\"severity\":"<<s<<",\"waiting\":"<<w<<",\"treated\":"<<t<<'}';}long seconds=0;for(auto&p:treated)seconds+=p.waitSeconds;a<<"],\"waiting\":"<<q.size()<<",\"treated\":"<<treated.size()<<",\"averageWaitingMinutes\":"<<(treated.empty()?0:seconds/(60*treated.size()))<<'}';return a.str();}if(method=="GET"&&path=="/api/health")return "{\"ok\":true}";
 if(method=="GET"&&path=="/api/dashboard"){int critical=0;long wait=0;for(auto&p:q)critical+=p.severity==5;for(auto&p:treated)wait+=p.waitSeconds;std::ostringstream o;o<<"{\"total\":"<<q.size()+treated.size()<<",\"waiting\":"<<q.size()<<",\"critical\":"<<critical<<",\"treated\":"<<treated.size()<<",\"avgWaitingMinutes\":"<<(treated.empty()?0:wait/(60*treated.size()))<<",\"queue\":"<<arr(q)<<"}";return o.str();}
 if(method=="GET"&&path.rfind("/api/patients/",0)==0){std::string id=path.substr(14);if(auto p=heap.searchPatient(id))return "{\"status\":\"waiting\",\"patient\":"+js(*p)+"}";for(auto&p:treated)if(p.patientID==id)return "{\"status\":\"treated\",\"patient\":"+js(p)+"}";return "{\"error\":\"Patient not found\"}";}
 if(method=="POST"&&path=="/api/patients"){Patient p;do{p.patientID="ER-"+std::to_string(std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::system_clock::now().time_since_epoch()).count())+"-"+std::to_string(rand());}while(heap.searchPatient(p.patientID)||std::any_of(treated.begin(),treated.end(),[&](const Patient&x){return x.patientID==p.patientID;}));p.name=field(body,"name");p.age=atoi(field(body,"age").c_str());p.gender=field(body,"gender");p.condition=field(body,"condition");p.severity=atoi(field(body,"severity").c_str());p.originalSeverity=p.severity;p.emergencyCategory=field(body,"emergencyCategory");p.arrivalTime=now();p.arrivalEpoch=std::time(nullptr);if(p.name.empty()||p.age<1||p.age>120||p.severity<1||p.severity>5||p.condition.empty())return "{\"error\":\"Name, valid age, condition and severity (1–5) are required\"}";heap.insertPatient(p);db.save(heap.displayPatients(),treated);return js(p);}
 if(method=="POST"&&path=="/api/patients/treat-next"){if(!heap.size())return "{\"error\":\"No patients waiting\"}";auto p=heap.extractMax();p.treatmentTime=now();p.waitSeconds=std::max<std::int64_t>(0,std::time(nullptr)-p.arrivalEpoch);treated.push_back(p);db.save(heap.displayPatients(),treated);return js(p);}
 auto slash=path.find_last_of('/');std::string id=path.substr(slash+1);if(method=="DELETE"&&path.rfind("/api/patients/",0)==0){bool ok=heap.removePatient(id);if(ok)db.save(heap.displayPatients(),treated);return ok?"{\"ok\":true}":"{\"error\":\"Patient not found\"}";}
 if(method=="PUT"&&path.find("/severity")!=std::string::npos){auto pos=path.find("/severity");id=path.substr(14,pos-14);int s=atoi(field(body,"severity").c_str());bool ok=heap.updateSeverity(id,s);if(ok)db.save(heap.displayPatients(),treated);return ok?"{\"ok\":true}":"{\"error\":\"Patient not found or invalid severity\"}";}
 return "{\"error\":\"Not found\"}";}
int main(){const char* configured=std::getenv("HOSPITAL_PORT");int port=configured?std::atoi(configured):8080;std::vector<Patient> initial;db.load(initial,treated);heap.build(initial);int server=socket(AF_INET,SOCK_STREAM,0),yes=1;setsockopt(server,SOL_SOCKET,SO_REUSEADDR,&yes,sizeof yes);sockaddr_in addr{};addr.sin_family=AF_INET;addr.sin_addr.s_addr=htonl(INADDR_LOOPBACK);addr.sin_port=htons(port);if(bind(server,(sockaddr*)&addr,sizeof addr)<0||listen(server,32)<0){std::cerr<<"Cannot bind/listen on port "<<port<<": "<<std::strerror(errno)<<"\n";return 1;}std::cout<<"Hospital API listening on http://localhost:"<<port<<"\n";for(;;){int c=accept(server,nullptr,nullptr);if(c<0)continue;std::string req;char buf[4096];size_t expected=0;for(;;){int n=read(c,buf,sizeof(buf));if(n<=0)break;req.append(buf,n);auto headerEnd=req.find("\r\n\r\n");if(headerEnd!=std::string::npos){if(!expected){expected=headerEnd+4;auto cl=req.find("Content-Length:");if(cl==std::string::npos)cl=req.find("content-length:");if(cl!=std::string::npos){cl=req.find(':',cl)+1;while(cl<req.size()&&req[cl]==' ')++cl;expected+=std::strtoul(req.c_str()+cl,nullptr,10);}}if(req.size()>=expected)break;}}if(req.empty()){close(c);continue;}auto e=req.find("\r\n");std::istringstream first(req.substr(0,e));std::string method,path,ver;first>>method>>path>>ver;auto b=req.find("\r\n\r\n");std::string body=b==std::string::npos?"":req.substr(b+4);std::string response=method=="OPTIONS"?"{}":route(method,path,body);int status=response.find("\"error\"")!=std::string::npos?400:200;std::string head="HTTP/1.1 "+std::to_string(status)+(status==200?" OK":" Bad Request")+"\r\nContent-Type: application/json\r\nAccess-Control-Allow-Origin: *\r\nAccess-Control-Allow-Methods: GET,POST,PUT,DELETE,OPTIONS\r\nAccess-Control-Allow-Headers: Content-Type\r\nConnection: close\r\nContent-Length: "+std::to_string(response.size())+"\r\n\r\n";if(method=="OPTIONS")response="{}";write(c,head.data(),head.size());write(c,response.data(),response.size());close(c);}}
